  if(auto X=Spec->TryGetField(TEXT("cast_shadow")))Entry->Descriptor.bCastShadow=Truth(X);if(auto X=Spec->TryGetField(TEXT("receives_decals")))Entry->Descriptor.bReceivesDecals=Truth(X);
  if(auto X=Spec->TryGetField(TEXT("override_materials"))){Entry->Descriptor.OverrideMaterials.Reset();if(Truth(X)){if(X->Type!=EJson::Array)return Fail(TEXT("override_materials must be an array or falsey"));for(const auto& Value:X->AsArray()){auto* Material=Resolve(Value,false);if(!Material||!CurrentFence())return false;if(!Material->IsA<UMaterialInterface>())return Fail(TEXT("Asset is not a MaterialInterface"));Entry->Descriptor.OverrideMaterials.Add(static_cast<UMaterialInterface*>(Material));}}}
